// ───────── CASE STUDIES (dossier 2026-27) with model answers ─────────
const CASES = [
{id:"c1", title:"Case 1 · Pedro & María's scooter start-up", units:"Units 2–3",
 facts:`Pedro and María want to launch an e-scooter rental platform (GPS app, mobile payment, park on public roads). Strategy: (a) launch, (b) expand, (c) maximise value, (d) <b>sell to a third party</b>. They need <b>Business Angels</b> first and later <b>venture capital</b>. María has an important personal wealth and wants to <b>limit her liability</b>.`,
 qs:[
 {q:"(1) What type of company could they create, given their strategy?",
  a:`A <b>capital company</b> (S.L. or S.A.). Their plan needs (i) <b>limited liability</b>, (ii) a capital divided into units that investors can <b>enter</b> and that can be <b>sold</b> at exit, and (iii) separation of <b>ownership and management</b> so investors don't have to run the business. A personalistic partnership (general or limited) fits none of this.`,
  keys:["Capital company","Limited liability","Entry of investors / exit","Partnership doesn't fit"]},
 {q:"(2) Why is a capital company more advisable than a partnership? (María wants to protect her wealth)",
  a:`<ul><li><b>Liability</b>: in a general partnership partners answer for company debts <b>personally, unlimitedly, subsidiarily and jointly & severally</b> (arts. 127, 148 CCom). In an S.L./S.A. members are <b>not personally liable</b> (art. 1 LSC) – María risks only her contribution.</li><li><b>Transferability</b>: partnership status can't be transferred without the others' consent (art. 143 CCom); shares/stakes can be transferred (S.A. freely, S.L. with restrictions) → needed for the sale.</li><li><b>Management</b> is separated from ownership (directors), so investors can join without managing.</li><li>Capital companies are the standard vehicle for investors; partnerships are rarely used today.</li></ul>
  <p class="tip">Caveat: limited liability only works after <b>registration</b> (otherwise irregular company) and if they don't abuse the company (<b>veil lifting</b>).</p>`,
  keys:["Art. 1 LSC – no personal liability","Partnership: personal, unlimited, subsidiary, joint & several","Transfer of status","Registration needed"]},
 {q:"(3) S.L. or S.A.? Why?",
  a:`<b>Recommendation: S.L. now.</b><ul><li>Minimum capital <b>€3,000</b> (S.A. €60,000), 100% paid but small.</li><li>No independent expert for non-cash contributions; fewer formalities, cheaper.</li><li><b>Flexible by-laws</b> (hybrid): founders can keep control (e.g. vote allocation, transfer restrictions, pre-emptive rights) while bringing in Business Angels.</li></ul>An <b>S.A.</b> becomes attractive if they need many investors, <b>free transferability</b> of shares or a <b>stock-market listing</b> (only S.A. can list). The S.L. can later be <b>transformed</b> into an S.A. (structural change).`,
  keys:["€3,000 vs €60,000","Fewer formalities","Control through flexible by-laws","Transform later / listing → S.A."]},
 {q:"(4) Main steps to set up the S.L.? Capital amount? Proportions? Can Pedro contribute his work? Can they invest through a company?",
  a:`<b>Steps</b>: 1. Negative <b>name certificate</b> from the Central Mercantile Registry · 2. Open a <b>bank account</b> in the name of the company in formation and deposit the capital (bank certificate) · 3. Obtain a provisional <b>NIF</b> · 4. Draft the <b>by-laws</b> (name, purpose, office, capital, stakes, management body…) · 5. Execute the <b>deed of incorporation before a notary</b> · 6. Tax formalities · 7. <b>Register</b> in the Mercantile Registry of the province (max 1 year) → legal personality; definitive NIF; tax/social security registrations.<br>
  <b>Capital</b>: at least <b>€3,000</b> (in the notes); in practice enough to fund the first phase and look credible to investors.<br>
  <b>Proportions</b>: free. A 50/50 split is common but risks <b>deadlock = paralysis of corporate bodies</b>, a legal cause of dissolution → if 50/50, add a deadlock clause in a shareholders' agreement (or e.g. 51/49).<br>
  <b>Pedro's work</b>: <b>cannot</b> be a capital contribution (art. 58.2 LSC). He can commit to work as an <b>ancillary commitment</b> (art. 86 LSC), free or paid, outside capital.<br>
  <b>Through a company</b>: <b>yes</b> – legal persons can be founders/members (e.g. each founder's own holding S.L.).`,
  keys:["Notary + Registry","€3,000","50/50 → paralysis risk","Work = ancillary commitment (art. 58.2, 86)","Holding company possible"]},
 {q:"(5) What is a shareholders' agreement, its content, should she sign it, and when?",
  a:`A <b>shareholders' agreement</b> (pacto de socios / parasocial) is a <b>private contract</b> between some or all shareholders regulating their relationship <b>beyond the by-laws</b>. It is <b>confidential</b>, not registered, and binds <b>only the signatories</b> (not the company or third parties) – that's why key points are often mirrored in the by-laws where possible.<br>
  <b>Typical content</b>: governance (board seats, <b>reserved matters / veto rights</b>, information rights) · <b>transfer restrictions</b>: lock-up, right of first refusal, <b>tag-along</b>, <b>drag-along</b> · <b>anti-dilution</b> & pre-emption · founders' dedication, <b>non-compete</b>, IP assignment · <b>vesting</b>, good/bad leaver · <b>deadlock</b> resolution · dividend policy · exit/sale provisions.<br>
  <b>Recommendation</b>: yes – sign one <b>at incorporation</b> between the founders (dedication, leaver, deadlock), and <b>amend/replace</b> it when investors enter (they will demand their own terms).`,
  keys:["Private contract, binds signatories","Governance & vetoes","Transfer clauses (ROFR, tag, drag)","Sign at incorporation + update with investors"]}
 ]},
{id:"c2", title:"Case 2 · Patinetes Eléctricos S.L.", units:"Units 4–7",
 facts:`<b>Facts 1</b>: after 2 years of losses, <b>equity €30,000</b> vs <b>share capital €90,000</b>. Pedro and María are <b>joint directors</b>.<br><b>Facts 2</b>: a <b>Business Angel</b> will invest <b>€100,000</b>; founders want to give <b>max 10%</b>. Capital €90,000 in <b>€1 par</b> stakes.<br><b>Facts 3</b>: subsidiary <b>PTEL S.L.U.</b> (100% owned, 5 employees, only serves the parent, no significant assets). Patinetes has 40 employees, all contracts, IP and licences. They will <b>merge</b>.`,
 qs:[
 {q:"1. Could Pedro and María be held liable for the capital impairment – as directors? as shareholders? What should they do?",
  a:`Equity €30,000 = <b>33% of capital</b> &lt; <b>½</b> (€45,000) → <b>legal cause of dissolution</b> (art. 363.1.e LSC) unless capital is increased or reduced sufficiently (and provided insolvency isn't due). The 2/3 mandatory reduction rule is only for S.A.<br>
  <b>As directors</b>: they must <b>convene the GM</b> (within <b>2 months</b>) to dissolve or adopt measures that fix the situation; if the GM doesn't agree, request <b>judicial dissolution</b>. Otherwise → <b>liability for company debts arising after the cause</b> (subsidiary, joint & several). If the company is <b>insolvent</b>, they must file within <b>2 months</b> or be liable for later debts (culpable insolvency).<br>
  <b>As shareholders</b>: <b>no</b> personal liability (capital company, art. 1 LSC).`,
  keys:["33% < 50% → dissolution cause","Convene GM (2 months)","Liable for later debts","Not as shareholders"]},
 {q:"2. Other management systems in S.L. and S.A.? Would liability change on a board?",
  a:`Four models (art. 210 LSC): <b>sole director</b>; <b>joint & several</b> (each acts alone); <b>joint</b> (act together; S.A. max 2); <b>board</b> (min 3; S.L. max 12; collegiate). <br>On a board the regime is the <b>same</b>: all members who adopted or executed the harmful act/omission are <b>jointly & severally liable</b> (art. 237), unless they prove they <b>expressly opposed</b>, <b>didn't know</b>, or did <b>everything possible</b> to avoid the damage. As joint directors both must act together, so both are equally responsible.`,
  keys:["4 models","Art. 237 joint & several","Exoneration: opposed / unaware / did everything"]},
 {q:"3. Measures to reverse the capital impairment?",
  a:`Goal: equity ≥ ½ capital.<ul><li><b>Capital increase</b> with new money – the BA's €100,000 (cash) → equity 130,000 vs capital 100,000 ✔.</li><li><b>Increase by offsetting loans</b> (shareholder loans turned into capital – S.L.: 100% liquid, mature, payable).</li><li><b>Capital reduction to compensate losses</b> (S.L. capital stays ≥ €3,000): e.g. reduce capital to €50,000 → equity 30,000 ≥ 25,000 ✔.</li><li><b>Accordion</b>: reduction + simultaneous increase.</li><li>Members' contributions to equity / return to profit.</li></ul>`,
  keys:["Cash increase (BA)","Loans → capital","Reduction for losses","Accordion"]},
 {q:"4. Main legal obligations of directors? Liabilities if breached?",
  a:`<b>Obligations</b>: act within law, by-laws and GM instructions; <b>duty of care</b> (orderly entrepreneur: prudence, competence, dedication, information, vigilance – incl. risk monitoring); <b>duty of loyalty</b> (no conflicts, secrecy, no competition); prepare <b>annual accounts</b>; convene the <b>ordinary GM</b> yearly and extraordinary GMs when required (dissolution causes); request <b>insolvency</b> on time.<br><b>Liabilities</b>: for <b>debts</b> (insolvency not filed / dissolution GM not convened → later debts) and for <b>damages</b> (art. 236: fault + damage + causal link; GM approval doesn't exonerate) via the <b>corporate</b> or <b>individual</b> action; plus <b>tax, labour and criminal</b> liability.`,
  keys:["Care + loyalty","Accounts, GM, insolvency","Debts vs damages","Corporate & individual actions"]},
 {q:"5 (i–iii). Type of capital increase? Other contributions? S.L. vs S.A.? Steps? Pre-emptive right?",
  a:`<b>Type</b>: increase with <b>cash contributions</b>, creating <b>new stakes</b> with a <b>share premium</b>. Others: <b>non-cash</b>, <b>offsetting loans</b>, <b>reserves</b>. Differences: S.A. needs an <b>expert report</b> for non-cash and <b>auditor's certificate</b> for loans (≥25% due, rest ≤5 years) and may <b>delegate</b> the increase to directors; S.L. needs 100% of loans due.<br>
  <b>Steps</b>: directors' proposal/report → GM convened (15 days, agenda + full text) → GM resolution (S.L.: <b>&gt; ½ of all votes</b>) → handling the pre-emptive right → subscription & payment (bank certificate) → <b>public deed</b> → <b>registration</b> of resolution + execution together.<br>
  <b>Pre-emptive right</b>: <b>yes</b>, Pedro and María have it (cash increase, ≥ 1 month). To let the BA in, they <b>waive it individually</b> (simplest, e.g. in a universal meeting) or the GM <b>excludes</b> it.`,
  keys:["Cash + new stakes + premium","Steps: report → GM → subscription → deed → registry","Pre-emptive right → waiver"]},
 {q:"5 (iv–vi). Pre-money valuation, anti-dilution mechanism and the figures of the resolution",
  a:`<div class="dia calc"><div>10% for €100,000 → post-money <b>€1,000,000</b> → <b>pre-money €900,000</b></div><div>Per existing stake: 900,000 ÷ 90,000 = <b>€10</b></div><div>New stakes N: N ÷ (90,000 + N) = 10% → <b>N = 10,000</b></div><div>Premium per stake = 10 − 1 = <b>€9</b> → total premium <b>€90,000</b></div></div>
  <b>Mechanism</b>: the <b>share premium</b> – the BA pays the real value (€10) instead of par (€1), so the founders' stakes aren't diluted in value.<br><br>
  <i>"To increase the corporate capital of the Company, currently € 90,000, by € <b>10,000</b>, by creating <b>10,000</b> new shares, numbered from 90,001 to <b>100,000</b>, both inclusive. Consequently, the number of shares shall be <b>100,000</b>, with a face value of € 1 each. The new shares are created with a total issue premium of € <b>90,000</b>, resulting in an issue premium of € <b>9</b> per share. Therefore, the issued share capital and issue premium total € <b>100,000</b>. Consequently, the corporate capital shall be € <b>100,000</b>, represented by <b>100,000</b> shares, with a face value of € 1 each, numbered from 1 to <b>100,000</b>, both inclusive."</i>`,
  keys:["Pre-money €900,000","10,000 new stakes","€9 premium / €90,000","Capital €100,000"]},
 {q:"6. Which company should absorb which?",
  a:`<b>PATINETES ELÉCTRICOS, S.L. absorbs PTEL, S.L.U.</b> Patinetes holds the 40 employees, all client and supplier contracts, the IP (trademarks, patents, domains) and the <b>licences and permits</b>. If PTEL absorbed Patinetes, all of these would have to pass to PTEL by universal succession – administrative licences may not be transferable, contracts may contain change-of-control clauses, and registrations would have to be updated. Absorbing the small subsidiary moves almost nothing (5 employees, no significant assets).`,
  keys:["Patinetes = absorbing","Licences/contracts/IP stay put","PTEL extinguished"]},
 {q:"7. Type of merger and requirements avoided?",
  a:`<b>Merger by absorption of a wholly-owned subsidiary</b> – a <b>special merger</b> (art. 53 RDLME). Avoided: <b>exchange ratio</b> (no new shares to PTEL's member – it's Patinetes itself), <b>capital increase</b> of the absorbing company, <b>directors' report</b> and <b>independent expert report</b>, and <b>approval by the GM of the absorbed company</b>. A simplified common draft is enough.`,
  keys:["Absorption of 100% subsidiary","Art. 53 RDLME","No exchange ratio / capital increase / reports / absorbed GM"]},
 {q:"8. Procedure in chronological order",
  a:`<ol><li>Directors of both companies draw up and sign the (simplified) <b>common draft terms of merger</b>.</li><li><b>Publication/deposit</b> of the draft in the Registry or on the websites, at least <b>1 month</b> before the GM (or individual notice; unanimous universal GM avoids it).</li><li><b>Merger balance sheets</b> (≤ 6 months; audited if required).</li><li><b>GM of Patinetes approves</b> the merger within <b>6 months</b> of the draft (PTEL's GM not needed).</li><li><b>Publication</b> of the resolution in the BORME + a newspaper, or individual written notice to members and creditors.</li><li><b>1-month creditors' opposition</b> period.</li><li><b>Public deed</b> of merger before a notary.</li><li><b>Registration</b> in the Mercantile Registry → merger effective, PTEL <b>extinguished</b> and its entries cancelled.</li></ol>`,
  keys:["Draft → publish → balance → GM → publish → 1 month → deed → registry"]},
 {q:"9. When is the merger effective legally and for accounting?",
  a:`<b>Legally</b>: on <b>registration</b> of the merger deed in the Mercantile Registry (universal succession, extinction of PTEL).<br><b>Accounting</b>: from the date stated in the merger draft from which PTEL's operations are considered carried out on behalf of Patinetes (under the accounting rules, typically the start of the financial year in which the merger is approved for group companies) – it can be <b>earlier</b> than the legal effect.`,
  keys:["Legal: registration","Accounting: date in the draft (retroactive)"]},
 {q:"10. Reasons for the merger? Should they be recorded in the merger project?",
  a:`<b>Reasons</b>: PTEL lost its purpose (only serves the parent) → <b>simplify</b> the group, <b>cut costs</b> (one set of accounts, audits, tax filings, governance), integrate the marketing team, synergies, single brand/contract holder.<br><b>Recording them</b>: not a mandatory item of the simplified draft, but <b>convenient</b>: it shows the economic rationale to members and creditors (transparency) and documents <b>valid economic reasons</b>, relevant e.g. for the tax-neutral merger regime.`,
  keys:["Simplification & cost savings","Transparency","Valid economic reasons (tax)"]}
 ]},
{id:"c3", title:"Case 3 · Advertising, cartels & IP", units:"Units 8–9",
 facts:`Part I: <b>KFC</b> parodies Trump's "nuclear button" tweet against <b>Ronald McDonald</b> ("my box meal is bigger and more powerful… and has gravy") · a cosmetics brand labels products "<b>100% natural</b>" though they contain chemicals.<br>Part II: software capping travel agencies' discounts at <b>3%</b> · a poster seller on <b>Amazon</b> using a pricing algorithm.<br>Part III: a company claims royalties for its registered "<b>Black Friday</b>" mark · competitors copy a start-up's registered <b>EU design</b> (webcam cover) · Apple employee's daughter leaks the new <b>iPhone</b> (trade secrets).`,
 qs:[
 {q:"I.1 What type of advertising is the KFC tweet? Terms under EU law?",
  a:`<b>Comparative advertising</b>: it identifies a competitor (McDonald's) by its mascot. Under Directive 2006/114/EC (art. 4) and the LCD (art. 10) it's permitted only if it: is <b>not misleading</b>; compares goods meeting the <b>same needs/purpose</b>; <b>objectively</b> compares <b>material, relevant, verifiable, representative</b> features (e.g. price); doesn't <b>discredit/denigrate</b> the competitor or its marks; doesn't create <b>confusion</b>; doesn't take <b>unfair advantage</b> of the competitor's mark/reputation; doesn't present goods as <b>imitations</b>.`,
  keys:["Comparative advertising","Same purpose","Objective & verifiable","No denigration / unfair advantage of mark"]},
 {q:"I.2 Does the tweet breach EU unfair-competition rules?",
  a:`Arguments <b>against</b> it: "bigger and more powerful" is <b>not an objective, verifiable</b> comparison; it <b>ridicules</b> the competitor ("big shoed, red nosed regime") and uses its mascot (a trademark) to ride on McDonald's fame → possibly <b>denigrating</b> and taking <b>unfair advantage</b>.<br>Arguments <b>for</b>: it's obvious <b>humour/parody</b> (puffery) no average consumer takes literally; same type of product (burgers); no real confusion.<br><b>Conclusion</b>: under a strict reading of the conditions it is <b>arguably unlawful</b> comparative advertising (non-verifiable claim + mocking a competitor's mark), although in practice such humorous campaigns are often tolerated. Show both sides in the exam.`,
  keys:["Not verifiable","Denigration / use of mark","Humour defence","Reasoned conclusion"]},
 {q:"I.Section 2 – \"100% natural\" with chemicals: what advertising and which actions?",
  a:`<b>Misleading advertising</b>: false information about <b>essential characteristics</b> (composition) able to distort consumers' decisions – a misleading act (art. 5 LCD) and misleading practice towards consumers (Dir. 2005/29/EC).<br><b>Actions</b> (art. 32 LCD) by competitors, consumers and consumer associations: <b>declaratory</b> action, <b>cessation</b> (stop) and prohibition of repetition, <b>removal of effects</b>, <b>rectification</b> of misleading information, <b>damages</b> (if fault), <b>unjust enrichment</b>; plus complaints to consumer authorities/self-regulation (Autocontrol), which may sanction.`,
  keys:["Misleading advertising","Essential characteristics","Cessation, rectification, damages"]},
 {q:"II.1 What is a cartel? Examples.",
  a:`A <b>secret agreement or concerted practice between competitors</b> to avoid competing: <b>fixing prices</b>, <b>sharing markets/customers</b>, <b>limiting production</b>, <b>bid rigging</b> (art. 101 TFEU, art. 1 LDC). Examples: European truck makers fixing prices; producers agreeing quotas; companies agreeing who wins public tenders. Cartels are the most serious infringement: never "minor importance", fines up to <b>10%</b> of turnover, <b>leniency</b> for the first whistle-blower.`,
  keys:["Agreement between competitors","Prices / markets / output","Never de minimis","Leniency"]},
 {q:"II.2 Can the two algorithm cases be sanctioned?",
  a:`<b>Travel agencies (3% cap)</b>: if the agencies <b>knew</b> of the system-imposed cap and kept using it, they engaged in a <b>concerted practice</b> to fix (minimum) prices via the platform – sanctionable under art. 101 TFEU (CJEU <i>Eturas</i>, 2016: an agency could escape only by publicly distancing itself). The software provider can be liable as a <b>facilitator</b>.<br><b>Posters on Amazon</b>: a <b>unilateral</b> repricing algorithm is lawful in itself. It's a <b>cartel</b> if it implements an <b>agreement with competitors</b> not to undercut each other (UK <i>posters</i> case, 2016) – then fines, nullity and possible leniency apply. Algorithms don't change the rules: <b>the agreement</b> is what matters.`,
  keys:["Concerted practice (Eturas)","Unilateral algorithm OK","Agreement → cartel","Fines up to 10%"]},
 {q:"III.1 What is a famous (renowned) trademark and how is it protected?",
  a:`A trademark <b>generally known</b> by the relevant public (art. 8 LM) thanks to prestige/geographic reach. Protection: even <b>unregistered</b> it enjoys rights like a registered one, and the owner can stop use <b>outside its classes</b> (exception to specialty) if it takes unfair advantage of or harms its reputation. Examples: <b>ZARA</b> (won against "Zara Tanzania Adventures"), Coca-Cola, Apple, Google.`,
  keys:["Generally known","Beyond its class","Even unregistered","Examples"]},
 {q:"III.2–3 Black Friday: can the shop ignore the royalty demand? Legal solution?",
  a:`<b>Yes, largely.</b> "Black Friday" describes a well-known <b>sales event</b> – a sign <b>devoid of distinctiveness</b> / <b>customary</b> in trade / descriptive of the <b>time</b> of the service → an <b>absolute prohibition</b> (art. 5 LM). Using the words <b>descriptively</b> (to announce discounts) isn't use as a trademark.<br><b>Solution</b>: bring (or counterclaim) a <b>nullity action</b> on absolute grounds – <b>no time limit</b> – or rely on it in defence; meanwhile use the expression descriptively, not as a brand. (In Spain the courts did annul most of that registration for these reasons.)`,
  keys:["Absolute prohibition (generic/descriptive)","Descriptive use ≠ trademark use","Nullity action – imprescriptible"]},
 {q:"III.Section 2 – Copied EU design: preventive measures and actions?",
  a:`<b>Prevent</b>: register the <b>design</b> (EU registered design – done), register the <b>trademark</b>, protect technical features with a <b>patent/utility model</b>, use NDAs, monitor the market, customs watch.<br><b>Once copied</b>: <b>cease-and-desist</b> letter; <b>infringement action</b> (cessation, withdrawal/destruction of copies, <b>damages</b>, publication of the judgment); <b>interim injunctions</b>; <b>customs</b> seizure; subsidiarily <b>unfair imitation</b> (LCD) if there's risk of association or exploitation of effort.`,
  keys:["Register designs/marks/patents","Cease & desist","Infringement action + damages","Interim/customs measures"]},
 {q:"III.Section 3 – Mechanisms to protect business innovations and their differences",
  a:`<table class="tbl"><tr><th>Tool</th><th>Registration</th><th>Duration</th><th>Note</th></tr><tr><td>Patent</td><td>Yes (OEPM)</td><td>20 yrs, not renewable</td><td>Public disclosure; must exploit</td></tr><tr><td>Utility model / design</td><td>Yes</td><td>Shorter / renewable periods</td><td>Practical / aesthetic creations</td></tr><tr><td>Trademark</td><td>Yes</td><td>10 yrs renewable ∞</td><td>Signs, not technology</td></tr><tr><td>Copyright</td><td>No</td><td>Long</td><td>Works, software</td></tr><tr><td><b>Trade secret</b></td><td><b>No</b></td><td>While secret</td><td>Needs secrecy + commercial value + <b>reasonable measures</b> (NDAs); no protection vs independent discovery (Act 1/2019, Dir. 2016/943)</td></tr></table>The iPhone leak = <b>disclosure of a trade secret</b> in breach of confidentiality → dismissal, damages, injunctions; also unfair competition (violation of secrets).`,
  keys:["Patent vs secret","Registration vs none","Duration","Reasonable measures"]}
 ]}
];

